import unicodedata


def strip_accents(text):
    return ''.join(ch for ch in unicodedata.normalize('NFKD', text) if not unicodedata.combining(ch))

def simple_stem(word):
    w = word.lower()
    for suf in ('ing', 'ed', 'ly', 'es', 's'):
        if w.endswith(suf) and len(w) - len(suf) >= 3:
            w = w[:-len(suf)]
            break
    if len(w) >= 2 and w[-1] == w[-2] and w[-1] not in 'aeiou':
        w = w[:-1]
    return w

def lemmatize(word, pos, lemma_dict):
    w = word.lower()
    return lemma_dict.get((w, pos), w)

import math


def perplexity(probs):
    if any(p == 0 for p in probs):
        return float('inf')
    return round(math.exp(-sum(math.log(p) for p in probs) / len(probs)), 4)

import math


def tf_idf(term_count, doc_length, n_docs, doc_freq):
    if doc_freq == 0 or doc_length == 0:
        return 0.0
    return round(term_count / doc_length * math.log10(n_docs / doc_freq), 4)

def bag_of_words(docs):
    vocab = sorted({t for d in docs for t in d})
    return vocab, [[d.count(w) for w in vocab] for d in docs]

import math


def search(query, docs):
    n = len(docs)
    scores = {}
    for doc_id, toks in docs.items():
        score = 0.0
        for term in query:
            df = sum(term in d for d in docs.values())
            if df and toks:
                score += toks.count(term) / len(toks) * math.log10(n / df)
        scores[doc_id] = score
    return sorted((d for d, s in scores.items() if s > 0), key=lambda d: (-scores[d], d))

def inverted_index(docs):
    index = {}
    for doc_id, toks in docs.items():
        for tok in toks:
            index.setdefault(tok, set()).add(doc_id)
    return {tok: sorted(ids) for tok, ids in index.items()}

import math


def cosine_similarity(a, b):
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    if na == 0 or nb == 0:
        return 0.0
    return round(sum(x * y for x, y in zip(a, b)) / (na * nb), 4)

