def _cos(a, b):
    na = math.sqrt(sum(x * x for x in a))
    nb = math.sqrt(sum(x * x for x in b))
    return 0.0 if na == 0 or nb == 0 else sum(x * y for x, y in zip(a, b)) / (na * nb)


def nearest_word(vector, embeddings, exclude):
    candidates = [w for w in embeddings if w not in exclude]
    return min(candidates, key=lambda w: (-round(_cos(vector, embeddings[w]), 9), w))

def char_ngrams(word, min_n, max_n):
    w = f'<{word}>'
    grams = []
    for n in range(min_n, max_n + 1):
        for i in range(len(w) - n + 1):
            g = w[i:i + n]
            if g not in grams:
                grams.append(g)
    if w not in grams:
        grams.append(w)
    return grams

def oov_vector(word, ngram_vectors, min_n, max_n):
    w = f'<{word}>'
    grams = {w[i:i + n] for n in range(min_n, max_n + 1) for i in range(len(w) - n + 1)} | {w}
    known = [ngram_vectors[g] for g in sorted(grams) if g in ngram_vectors]
    if not known:
        return None
    return [round(sum(col) / len(known), 4) for col in zip(*known)]

def glove_weight(x, x_max=100, alpha=0.75):
    if x == 0:
        return 0.0
    return round(min(1.0, (x / x_max) ** alpha), 4)

def cooccurrence(tokens, window):
    counts = {}
    for i in range(len(tokens)):
        for j in range(i + 1, min(len(tokens), i + window + 1)):
            if tokens[i] == tokens[j]:
                continue
            key = tuple(sorted((tokens[i], tokens[j])))
            counts[key] = counts.get(key, 0) + 1
    return counts

def viterbi(words, states, start, trans, emit):
    best = {s: (start[s] * emit[s].get(words[0], 0), [s]) for s in states}
    for w in words[1:]:
        new = {}
        for s in states:
            prob, path = max(((best[p][0] * trans[p][s], best[p][1]) for p in states), key=lambda t: t[0])
            new[s] = (prob * emit[s].get(w, 0), path + [s])
        best = new
    top = max(states, key=lambda s: best[s][0])
    return best[top][1]

def sequence_prob(tags, words, start, trans, emit):
    p = start[tags[0]] * emit[tags[0]].get(words[0], 0)
    for i in range(1, len(tags)):
        p *= trans[tags[i - 1]][tags[i]] * emit[tags[i]].get(words[i], 0)
    return round(p, 6)

def valid_bio(tags):
    prev = 'O'
    for t in tags:
        if t.startswith('I-'):
            if prev == 'O' or prev[2:] != t[2:]:
                return False
        prev = t
    return True

def bio_spans(tokens, tags):
    spans, cur = [], None
    for tok, tag in zip(tokens, tags):
        if tag.startswith('B-'):
            if cur:
                spans.append(cur)
            cur = (tag[2:], [tok])
        elif tag.startswith('I-') and cur and cur[0] == tag[2:]:
            cur[1].append(tok)
        else:
            if cur:
                spans.append(cur)
            cur = None
    if cur:
        spans.append(cur)
    return [(t, ' '.join(words)) for t, words in spans]

import math


def nb_classify(tokens, priors, likelihoods, unknown=1e-6):
    def score(c):
        return math.log(priors[c]) + sum(math.log(likelihoods[c].get(w, unknown)) for w in tokens)
    return min(priors, key=lambda c: (-score(c), c))

import math


def rnn_step(w_hh, h_prev, w_xh, x, b):
    return round(math.tanh(w_hh * h_prev + w_xh * x + b), 4)

def gradient_after(factor, steps):
    g = factor ** steps
    if abs(g) < 0.001:
        status = 'VANISHING'
    elif abs(g) > 1000:
        status = 'EXPLODING'
    else:
        status = 'STABLE'
    return {'gradient': round(g, 6), 'status': status}

def gru_update(z, h_prev, h_candidate):
    if isinstance(h_prev, list):
        return [gru_update(z, a, b) for a, b in zip(h_prev, h_candidate)]
    return round((1 - z) * h_prev + z * h_candidate, 4)

def bidirectional(xs, step, h0=0.0):
    fwd, h = [], h0
    for x in xs:
        h = step(h, x)
        fwd.append(h)
    bwd, h = [], h0
    for x in reversed(xs):
        h = step(h, x)
        bwd.append(h)
    bwd.reverse()
    return list(zip(fwd, bwd))

def sentence_embedding(tokens, vectors):
    known = [vectors[t] for t in tokens if t in vectors]
    if not known:
        return None
    return [round(sum(col) / len(known), 4) for col in zip(*known)]

def decoder_inputs(targets, predictions, teacher):
    source = targets if teacher else predictions
    return ['<s>'] + list(source[:len(targets) - 1])

