def head_dim(d_model, heads):
    if heads <= 0 or d_model % heads:
        raise ValueError('d_model must divide evenly into a positive number of heads')
    return d_model // heads

def split_heads(vector, heads):
    if heads <= 0 or len(vector) % heads:
        raise ValueError('length must be divisible by heads')
    size = len(vector) // heads
    return [vector[i * size:(i + 1) * size] for i in range(heads)]


def merge_heads(chunks):
    return [x for chunk in chunks for x in chunk]

import math


def positional_encoding(pos, i, d_model):
    angle = pos / 10000 ** (2 * (i // 2) / d_model)
    return round(math.sin(angle) if i % 2 == 0 else math.cos(angle), 4)

