def rotate_pair(x, y, pos, theta):
    a = pos * theta
    return (round(x * math.cos(a) - y * math.sin(a), 4), round(x * math.sin(a) + y * math.cos(a), 4))

import math


def layer_norm(x, eps=1e-5):
    mean = sum(x) / len(x)
    var = sum((v - mean) ** 2 for v in x) / len(x)
    return [round((v - mean) / math.sqrt(var + eps), 4) for v in x]

def merge_pair(tokens, pair, new_token):
    out, i = [], 0
    while i < len(tokens):
        if i + 1 < len(tokens) and (tokens[i], tokens[i + 1]) == tuple(pair):
            out.append(new_token)
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out

def most_frequent_pair(tokens):
    counts = {}
    for pair in zip(tokens, tokens[1:]):
        counts[pair] = counts.get(pair, 0) + 1
    if not counts:
        return None
    return max(counts, key=counts.get)

def bert_mask_plan(n_tokens):
    selected = round(n_tokens * 0.15)
    mask = round(selected * 0.8)
    random_count = round(selected * 0.1)
    return {'selected': selected, 'mask': mask, 'random': random_count, 'unchanged': selected - mask - random_count}

def kv_cache_bytes(layers, heads, head_dim, seq_len, batch=1, bytes_per_value=2):
    return 2 * layers * heads * head_dim * seq_len * batch * bytes_per_value


def to_gib(n):
    return round(n / 1024 ** 3, 2)

def best_span(start_logits, end_logits, max_len):
    best, best_score = None, None
    for i in range(len(start_logits)):
        for j in range(i, min(len(end_logits), i + max_len)):
            score = start_logits[i] + end_logits[j]
            if best_score is None or score > best_score:
                best, best_score = (i, j), score
    return best

import string


def _norm(s):
    text = ''.join(ch for ch in s.lower() if ch not in string.punctuation)
    return ' '.join(w for w in text.split() if w not in {'a', 'an', 'the'})


def exact_match(prediction, truth):
    return 1 if _norm(prediction) == _norm(truth) else 0

def check_two_stage(corpus_size, k1, k2):
    problems = []
    if k1 >= corpus_size:
        problems.append('K1_NOT_SMALLER_THAN_CORPUS')
    if k2 >= k1:
        problems.append('K2_NOT_SMALLER_THAN_K1')
    if k2 <= 0:
        problems.append('K2_NOT_POSITIVE')
    return problems

def top_p(probs, p):
    keep, total = [], 0.0
    for tok in sorted(probs, key=lambda t: (-probs[t], t)):
        keep.append(tok)
        total += probs[tok]
        if round(total, 9) >= p:
            break
    return keep

import math


def brevity_penalty(candidate_len, reference_len):
    if candidate_len == 0:
        return 0.0
    if candidate_len > reference_len:
        return 1.0
    return round(math.exp(1 - reference_len / candidate_len), 4)

from collections import Counter


def rouge1_recall(candidate, reference):
    if not reference:
        return 0.0
    cand = Counter(candidate)
    overlap = sum(min(n, cand[w]) for w, n in Counter(reference).items())
    return round(overlap / len(reference), 4)

def lora_params(d, k, r):
    full = d * k
    lora = r * (d + k)
    return {'full': full, 'lora': lora, 'saving_pct': round((1 - lora / full) * 100, 2)}

def lora_merge(W, B, A, alpha, r):
    scale = alpha / r
    return [[round(W[i][j] + scale * sum(B[i][t] * A[t][j] for t in range(len(A))), 4)
             for j in range(len(W[0]))] for i in range(len(W))]

