import re
from collections import Counter


def _vec(text, stopwords):
    words = re.sub(r'[^a-z0-9 ]', ' ', text.lower()).split()
    return Counter(w for w in words if w not in stopwords)


def _cos(a, b):
    dot = sum(a[w] * b.get(w, 0) for w in a)
    na = math.sqrt(sum(v * v for v in a.values()))
    nb = math.sqrt(sum(v * v for v in b.values()))
    return 0.0 if na == 0 or nb == 0 else dot / (na * nb)


def retrieve(question, passages, stopwords, k):
    q = _vec(question, stopwords)
    scored = {pid: _cos(q, _vec(text, stopwords)) for pid, text in passages.items()}
    return sorted((p for p, s in scored.items() if s > 0), key=lambda p: (-round(scored[p], 9), p))[:k]

def audit_nlp_capstone(results):
    passed = sorted(n for n, s in results.items() if s >= 70)
    failed = sorted(n for n, s in results.items() if s < 70)
    average = round(sum(results.values()) / len(results), 1) if results else 0.0
    return {'passed': passed, 'failed': failed, 'average': average,
            'certified': bool(results) and not failed and average >= 80}
